<script>
import DataQualityWorkbench from './DataQualityWorkbench.vue'
export default { name: 'TransformationPreview', components: { DataQualityWorkbench }, props: { preview: Object }, methods: { columns(frame) { return frame.schema?.columns?.map(item => item.name) || Object.keys(frame.sample?.[0] || {}) } } }
</script>
<template><section v-if="preview" class="phase3-workbench" aria-label="变更预览"><h3>版本 {{ preview.dataset_version_id }} 的变更预览</h3><p>原版本保留；确认后保存为新版本。</p><div v-for="(frame, key) in { before: preview.before, after: preview.after }" :key="key"><h4>{{ key === 'before' ? '变更前' : '变更后' }} · {{ frame.row_count }} 行 · {{ frame.column_count }} 列</h4><DataQualityWorkbench v-if="frame.quality" :result="frame.quality" /><div class="table-wrap phase3-table"><table class="data-table"><thead><tr><th v-for="column in columns(frame)" :key="column">{{ column }}</th></tr></thead><tbody><tr v-for="(row, index) in frame.sample || []" :key="index"><td v-for="column in columns(frame)" :key="column">{{ row[column] ?? '—' }}</td></tr></tbody></table></div><p>显示服务器提供的有限样例。</p></div><p v-if="preview.result?.source_versions">来源版本：左 {{ preview.result.source_versions.left }} · 右 {{ preview.result.source_versions.right }}</p><p v-if="preview.result?.kind === 'join'">预计 {{ preview.result.row_count }} 行 · 左键唯一值 {{ preview.result.left_key_cardinality }} · 右键唯一值 {{ preview.result.right_key_cardinality }} · 未匹配左行 {{ preview.result.unmatched_left_rows }} · 未匹配右行 {{ preview.result.unmatched_right_rows }}。预览通过表示键为空与声明关系检查已通过。</p><p v-for="(step, index) in preview.result?.steps || []" :key="index">步骤 {{ index + 1 }} · {{ step.operation }} · {{ step.row_count }} 行 · 改变 {{ step.changed_cells }} 个单元格 · 新增缺失 {{ step.added_missing }}</p><p v-for="note in preview.result?.limitations || []" :key="note">{{ note }}</p></section></template>
